<?php
declare(strict_types=1);namespace Vendi\Integrations\Skydropx;use PDO;use RuntimeException;use Vendi\Integrations\HttpClient;
final class SkydropxService{private string$base='https://api-pro.skydropx.com';public function __construct(private PDO$db,private ?HttpClient$http=null){}private function cfg(int$b):array{$q=$this->db->prepare("SELECT config_json FROM integration_credentials WHERE business_id=? AND provider='skydropx' AND active=1 ORDER BY branch_id IS NOT NULL DESC LIMIT 1");$q->execute([$b]);$c=json_decode((string)$q->fetchColumn(),true)?:[];if(empty($c['client_id'])||empty($c['client_secret']))throw new RuntimeException('Skydropx no está configurado.');return$c;}private function token(int$b):string{$c=$this->cfg($b);if(!empty($c['access_token'])&&!empty($c['expires_at'])&&strtotime($c['expires_at'])>time()+60)return$c['access_token'];$h=$this->http??new HttpClient;$r=$h->request('POST',$this->base.'/api/v1/oauth/token',[],['grant_type'=>'client_credentials','client_id'=>$c['client_id'],'client_secret'=>$c['client_secret']]);$token=(string)($r['access_token']??'');if(!$token)throw new RuntimeException('Skydropx no devolvió token.');return$token;}private function call(int$b,string$m,string$path,?array$body=null):array{return($this->http??new HttpClient)->request($m,$this->base.$path,['Authorization'=>'Bearer '.$this->token($b)],$body);}public function quote(int$b,array$q):array{return$this->call($b,'POST','/api/v1/quotations',['quotation'=>$q]);}public function quotation(int$b,string$id):array{return$this->call($b,'GET','/api/v1/quotations/'.rawurlencode($id));}public function createShipment(int$b,string$rateId,string$format='thermal'):array{return$this->call($b,'POST','/api/v2/shipments',['shipment'=>['rate_id'=>$rateId,'unique_shipment'=>true,'printing_format'=>$format]]);}public function track(int$b,string$tracking,string$carrier):array{return$this->call($b,'GET','/api/v1/shipments/tracking?tracking_number='.rawurlencode($tracking).'&carrier_name='.rawurlencode($carrier));}}
